select energy_manager.load_cards($cards$[
{"id":"p4-075","paper":4,"topic":"Textile processing","kind":"problem","front":"A stenter delivers 1200 kg/h of cloth at 5% moisture. Cloth enters at 60% moisture (wet basis) and is heated from 30 °C to 85 °C. Stenter efficiency is 50%. Heat comes from a thermic fluid heater (75% efficient) firing furnace oil (GCV 10,000 kcal/kg, density 0.92 kg/l). Find water evaporated, heat load and oil consumption in litres/h.","back":"Evaporation ≈ 1650 kg/h; heat load ≈ 9.82 lakh kcal/h; oil ≈ 262 kg/h ≈ 285 litres/h","explain":"Efficiency improvements multiply through: better stenter efficiency (more chambers, exhaust humidity control) and better heater efficiency both cut oil. Mechanical dewatering (padding/squeezing) before the stenter is the cheapest saving, because each kg of water removed mechanically saves about 600 kcal of thermal energy.","steps":[{"prompt":"Bone-dry cloth","answer":"1200 × 0.95 = 1140 kg/h","explain":"Outlet × (1 − moisture)."},{"prompt":"Wet inlet and water evaporated","answer":"Inlet = 1140/0.40 = 2850 kg/h; evaporated = 2850 − 1200 = 1650 kg/h","explain":"Wet-basis moisture."},{"prompt":"Drying heat load","answer":"1650 × [(85 − 30) + 540] = 9,81,750 kcal/h","explain":"Sensible + latent."},{"prompt":"Heat into stenter and heater","answer":"9,81,750/0.50 = 19,63,500; /0.75 = 26,18,000 kcal/h","explain":"Divide by each efficiency in series."},{"prompt":"Oil consumption","answer":"26,18,000/10,000 = 261.8 kg/h ÷ 0.92 = 284.6 l/h","explain":"kg = heat/GCV; litres = kg/density."}],"flash":false,"source":"BEE 2025 P4 N4D","order":4074},
{"id":"p4-076","paper":4,"topic":"Cement","kind":"fact","front":"What is the formula for the heat of formation of cement clinker (loss-free basis)?","back":"ΔH (kcal/kg clinker) = 2.22 Al₂O₃ + 6.48 MgO + 7.646 CaO − 5.116 SiO₂ − 0.59 Fe₂O₃ (oxides in %).","explain":"Typical ordinary clinker gives about 380–420 kcal/kg. This theoretical heat is the 'useful output' in a kiln heat balance. The real specific thermal energy consumption (often 700–800 kcal/kg in modern plants) is compared against it. Asked in both BEE 2023 and BEE 2024.","flash":false,"source":"BEE 2024 P4 N4C","order":4075},
{"id":"p4-077","paper":4,"topic":"Cement","kind":"fact","front":"In a cement rotary kiln, is the largest heat loss through hot clinker discharge?","back":"No. The largest losses are with the preheater exhaust gases and cooler vent air. Sensible heat in discharged clinker is comparatively small.","explain":"That is why waste-heat recovery boilers are fitted on preheater (PH) and air-quenching cooler (AQC) exhausts for power generation. BEE 2025 T/F: False.","flash":false,"source":"BEE 2025 P4 Q10","order":4076},
{"id":"p4-078","paper":4,"topic":"Steam systems","kind":"fact","front":"Is reducing make-up water the only reason to install a condensate recovery system?","back":"No. Condensate recovery also saves fuel (hot feed water), water-treatment chemicals and blowdown, and it improves feed-water quality.","explain":"Each 6 °C rise in feed-water temperature saves about 1% fuel, and condensate is often returned at 80–100 °C. Lower feed TDS means less blowdown and its heat loss. BEE 2025 T/F: False.","flash":false,"source":"BEE 2025 P4 Q8","order":4077},
{"id":"p4-079","paper":4,"topic":"PAT / benchmarking","kind":"fact","front":"How are energy savings converted to ESCerts under PAT for a thermal power plant?","back":"ESCerts = (baseline net HR − assessment net HR) (kcal/kWh) × baseline generation (kWh) / 10⁷, since 1 ESCert = 1 toe = 10⁷ kcal.","explain":"Example from BEE 2025: gross HR 2300 with 9% aux → net 2527.5. Against a baseline of 2600, the saving is 72.5 kcal/kWh. On 5000 MU that is about 36,264 ESCerts. Always convert gross HR to net HR first.","flash":false,"source":"BEE 2025 P4 L2","order":4078},
{"id":"p4-080","paper":4,"topic":"Waste minimisation","kind":"fact","front":"What are the main waste minimisation techniques?","back":"Source reduction (good housekeeping, input-material change, better process control, equipment modification, technology change), recycling (on-site recovery and reuse, useful by-products), and product modification.","explain":"Source reduction is preferred because it avoids the waste being generated at all. Recycling recovers value from waste already made. Each technique also cuts the energy embedded in the lost material.","flash":false,"source":"syllabus","order":4079},
{"id":"p4-b01-001","paper":4,"topic":"Boiler Performance","kind":"fact","front":"What is the main purpose of a boiler performance test?","back":"To find the boiler's actual efficiency and evaporation ratio, and compare them with design values or norms.","explain":"The test tracks day-to-day and season-to-season variation in efficiency and shows whether energy-efficiency improvements are working. Abnormal deviations can then be investigated and corrected.","flash":false,"source":"BEE Book 4 Ch 01 p21","order":4080},
{"id":"p4-b01-002","paper":4,"topic":"Boiler Performance","kind":"fact","front":"What steady-state procedure does British Standard BS 845:1987 specify for a boiler efficiency test?","back":"Run the boiler at steady load (generally full load) for one hour to stabilise, then take readings during the next hour of steady operation.","explain":"The efficiency is then calculated from those readings. Testing during warm-up from cold is not valid, so the boiler must be at steady load before readings are taken.","flash":false,"source":"BEE Book 4 Ch 01 p22","order":4081},
{"id":"p4-b01-003","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Which basis does BS 845 use for boiler efficiency: gross or net calorific value?","back":"Gross calorific value (GCV).","explain":"Efficiency is the useful heat available as a percentage of the total energy potentially available from burning the fuel, on a GCV basis. Keep GCV in mind when a question quotes a fuel's heating value.","flash":true,"source":"BEE Book 4 Ch 01 p22","order":4082},
{"id":"p4-b01-004","paper":4,"topic":"Boiler Performance","kind":"fact","front":"What do Part One and Part Two of BS 845 cover?","back":"Part One: standard boilers, where the indirect method is specified. Part Two: complex plant with many heat-flow channels, where direct and indirect methods apply in whole or in part.","explain":"Standard packaged boilers use the simpler indirect (heat-loss) approach. Complex plants need a full heat balance, so both methods can be used.","flash":false,"source":"BEE Book 4 Ch 01 p22","order":4083},
{"id":"p4-b01-005","paper":4,"topic":"Boiler Performance","kind":"fact","front":"What are ASME PTC-4-1 Part One and Part Two?","back":"Part One: direct method (input-output method). Part Two: indirect method (heat-loss method).","explain":"ASME PTC-4-1 is the Power Test Code for steam generating units. It uses the same two methods as the BS and Indian standards.","flash":false,"source":"BEE Book 4 Ch 01 p22","order":4084},
{"id":"p4-b01-006","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Do IS 8753 and BS 845 count blowdown as a loss in boiler efficiency?","back":"No. Most standards, including IS 8753 and BS 845, are designed for spot measurement and do not include blowdown as a loss.","explain":"Blowdown loss varies widely over a day, so a spot test misses it. When blowdown is significant, it must be added separately to get a true picture of boiler performance.","flash":true,"source":"BEE Book 4 Ch 01 p22","order":4085},
{"id":"p4-b01-007","paper":4,"topic":"Boiler Performance","kind":"fact","front":"What does the direct method need as inputs, and why is it called input-output?","back":"Only the useful output (steam) and the heat input (fuel). Efficiency = heat output / heat input x 100.","explain":"It needs few parameters and few instruments, so it is quick. That is why it is called the input-output method.","flash":false,"source":"BEE Book 4 Ch 01 p22","order":4086},
{"id":"p4-b01-008","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Name two demerits of the direct efficiency method.","back":"It gives no clue why efficiency is low, and it does not calculate the individual losses. Also, evaporation ratio and efficiency can mislead if the steam is wet due to carryover.","explain":"A low direct-method result tells you the boiler is underperforming, but not where the losses are. The indirect method is used to find the cause.","flash":false,"source":"BEE Book 4 Ch 01 p25","order":4087},
{"id":"p4-b01-009","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Why is the indirect method more accurate than the direct method?","back":"Measurement errors in the losses do not change the efficiency significantly, because each loss is a small fraction of the input.","explain":"A 1% error on a 90% efficiency reading moves the answer by 0.9 points. A 1% error on losses that total 10% moves it by only 0.1 points. See the worked error comparison in this chapter.","flash":false,"source":"BEE Book 4 Ch 01 p25","order":4088},
{"id":"p4-b01-010","paper":4,"topic":"Boiler Performance","kind":"fact","front":"List the eight heat losses used in the indirect method.","back":"L1 dry flue gas; L2 hydrogen in fuel; L3 moisture in fuel; L4 moisture in air; L5 partial combustion of C to CO; L6 surface radiation and convection; L7 unburnt in fly ash; L8 unburnt in bottom ash.","explain":"Efficiency = 100 minus the sum of all applicable losses. L1 to L6 apply to all fuels; L7 and L8 apply only to solid-fuel boilers.","flash":false,"source":"BEE Book 4 Ch 01 p26","order":4089},
{"id":"p4-b01-011","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Which two indirect-method losses apply only to solid-fuel boilers?","back":"L7 (unburnt carbon in fly ash) and L8 (unburnt carbon in bottom ash).","explain":"Liquid and gas fired boilers have no ash, so only L1 to L6 apply. Ash losses must be found by lab analysis of ash samples.","flash":true,"source":"BEE Book 4 Ch 01 p26","order":4090},
{"id":"p4-b01-012","paper":4,"topic":"Boiler Performance","kind":"fact","front":"What typical surface (radiation and convection) loss is assumed for an industrial fire-tube or packaged boiler?","back":"1.5 to 2.5%. Water-tube industrial boilers: 2 to 3%. Power station boilers: 0.4 to 1%.","explain":"These are assumed values based on boiler type and size. The loss can be calculated instead if the surface area and surface temperature are known.","flash":true,"source":"BEE Book 4 Ch 01 p32","order":4091},
{"id":"p4-b01-013","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Which single heat loss is usually the greatest in a boiler?","back":"Heat loss due to dry flue gas (L1), which is the largest boiler loss.","explain":"Dry flue gas loss depends on the mass of dry flue gas, its specific heat and the temperature rise of the flue gas above ambient.","flash":true,"source":"BEE Book 4 Ch 01 p29","order":4092},
{"id":"p4-b01-014","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Which flue gas measurement is recommended for excess air, and what if O2 and CO2 tests disagree?","back":"Measure O2 if possible; use CO2 only if O2 is not available. If the two disagree, check for stale chemicals, drifting calibration, or outside air leaking in under negative pressure.","explain":"Outside air entering through casing leaks lifts the O2 reading and lowers the CO2 reading. Always check instrument calibration and the chemicals before trusting a result.","flash":false,"source":"BEE Book 4 Ch 01 p28","order":4093},
{"id":"p4-b01-015","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Where should the flue gas sample and temperature be taken?","back":"At the boiler exit duct, after probing and traversing it to find the zone of maximum temperature.","explain":"The maximum-temperature zone usually coincides with the maximum gas flow, so it gives a representative sample for both temperature and gas analysis.","flash":false,"source":"BEE Book 4 Ch 01 p28","order":4094},
{"id":"p4-b01-016","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Why is carbon monoxide in flue gas a good indicator of combustion quality?","back":"CO is minimal with ordinary excess air, but it rises abruptly once combustion becomes incomplete. It is a sign of incomplete combustion with any carbon-bearing fuel.","explain":"CO shows incomplete combustion early, before the other flue gas readings change much. It is the one incomplete-combustion gas that can be measured conveniently in a boiler test.","flash":false,"source":"BEE Book 4 Ch 01 p28","order":4095},
{"id":"p4-b01-017","paper":4,"topic":"Boiler Performance","kind":"fact","front":"How long should a routine boiler efficiency test run in a normal production day?","back":"4 to 8 hours.","explain":"Planning must arrange manpower, fuel, water and instruments in advance, and tell the boiler supervisor and production department. The test must not be disrupted by lack of fuel or water.","flash":true,"source":"BEE Book 4 Ch 01 p29","order":4096},
{"id":"p4-b01-018","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Which losses or consumptions does the standard efficiency test NOT account for?","back":"Blowdown loss, soot blower steam, and auxiliary energy such as burner, fan and pump power.","explain":"These are real costs of running the boiler. They must be considered separately when comparing the test efficiency with total plant energy use.","flash":false,"source":"BEE Book 4 Ch 01 p28","order":4097},
{"id":"p4-b01-019","paper":4,"topic":"Boiler Performance","kind":"fact","front":"How often should an energy auditor carry out the boiler performance test as routine practice?","back":"Once in six months, and report the results to management for action.","explain":"Routine testing shows drift in efficiency over time. Results are compared with standard norms, and modifications are made where needed.","flash":true,"source":"BEE Book 4 Ch 01 p42","order":4098},
{"id":"p4-b01-020","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Name the factors that affect boiler performance.","back":"Periodic cleaning; periodic soot blowing; water treatment and blowdown control; draft control; excess air control; percentage loading; steam pressure and temperature; boiler insulation; quality of fuel.","explain":"These factors act alone or together, and show up in either boiler efficiency or evaporation ratio. Test results are used to decide which factor to correct.","flash":false,"source":"BEE Book 4 Ch 01 p42","order":4099},
{"id":"p4-b01-021","paper":4,"topic":"Boiler Performance","kind":"fact","front":"What is MCR (Maximum Continuous Rating) for a steam boiler?","back":"The maximum evaporation rate that can be sustained for 24 hours. It may be lower than a shorter-duration maximum rating.","explain":"MCR is the standard rated output of a steam boiler. It is a continuous, not a peak, figure.","flash":true,"source":"BEE Book 4 Ch 01 p42","order":4100},
{"id":"p4-b01-022","paper":4,"topic":"Boiler Performance","kind":"fact","front":"What is equivalent evaporation, and what is its reference point?","back":"The steam generation rate expressed as kg of steam per hour from and at 100 °C, i.e. the evaporation of 1 kg of water at 100 °C into steam at 100 °C.","explain":"Converting to a common reference point lets boilers of different pressures be compared by one number. It is the usual basis for stating boiler rating.","flash":false,"source":"BEE Book 4 Ch 01 p42","order":4101},
{"id":"p4-b01-023","paper":4,"topic":"Boiler Performance","kind":"fact","front":"What is the difference between primary and secondary air in a combustion system?","back":"Primary air is the part of the air supply that the fuel meets first. Secondary air is admitted in a second stage, usually under high pressure for solid fuels, to create turbulence and complete combustion.","explain":"Secondary air ensures good mixing with the combustion gases. Without it, combustion started by the primary air may stay incomplete.","flash":false,"source":"BEE Book 4 Ch 01 p42","order":4102},
{"id":"p4-b01-024","paper":4,"topic":"Boiler Performance","kind":"fact","front":"How is absolute pressure related to gauge pressure?","back":"Absolute pressure = gauge pressure + atmospheric pressure. A boiler gauge reading of 9 kg/cm² (g) is 10 kg/cm² (a).","explain":"The book's calculations use absolute pressure, so a gauge reading should be converted before it is used with steam property values.","flash":false,"source":"BEE Book 4 Ch 01 p42","order":4103},
{"id":"p4-b01-025","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Which instruments are used for indirect efficiency testing?","back":"A flue gas analyser (CO2, O2, CO); thermocouples or temperature indicators (flue gas, air, fuel, steam, surface); a manometer or draft gauge; TDS meters for water; and flow meters for steam, water, fuel and air.","explain":"The flue gas analyser and temperature readings drive most of the loss calculations. TDS and flow readings support the water and blowdown checks.","flash":false,"source":"BEE Book 4 Ch 01 p27","order":4104},
{"id":"p4-b01-026","paper":4,"topic":"Boiler Performance","kind":"fact","front":"Why must a steam flow meter reading be corrected for temperature and pressure?","back":"Because the steam's density changes with temperature and pressure, so a raw volume or differential reading does not give the true mass flow.","explain":"Modern variable-orifice or vortex-shedding meters are now practical for steam flow, unlike earlier orifice or venturi meters whose accuracy changed with flow rate.","flash":false,"source":"BEE Book 4 Ch 01 p24","order":4105},
{"id":"p4-b01-027","paper":4,"topic":"Boiler Performance","kind":"fact","front":"How should blowdown be handled during a direct-method test?","back":"Intermittent blowdown should be avoided during the trial. Continuous blowdown heat loss must be calculated and added to the heat in steam.","explain":"Blowdown removes hot water that is not counted as steam output, so it must be either avoided or corrected for in the heat output figure.","flash":false,"source":"BEE Book 4 Ch 01 p24","order":4106},
{"id":"p4-b01-028","paper":4,"topic":"Boiler Performance","kind":"fact","front":"What is the book's main reason that the indirect method is the more useful test?","back":"It gives the individual losses, so the operator can see why efficiency is low, and it is much less affected by measurement error.","explain":"A direct test only gives one number. The indirect method turns that number into a list of losses that can be attacked one by one.","flash":false,"source":"BEE Book 4 Ch 01 p21","order":4107},
{"id":"p4-b01-029","paper":4,"topic":"Boiler Performance","kind":"problem","front":"A coal-fired boiler generates 8 TPH of steam at 10 kg/cm² (g) and 180 °C, from feed water at 85 °C. Coal burnt is 1.6 TPH at GCV 4000 kcal/kg. Steam enthalpy is 665 kcal/kg. Find the boiler efficiency by the direct method and the evaporation ratio.","back":"Boiler efficiency = 72.5%. Evaporation ratio = 5 kg steam per kg coal.","explain":"Direct method uses only steam output and fuel input. The efficiency is about 72.5% on a GCV basis, and the evaporation ratio is 8 divided by 1.6.","flash":false,"source":"BEE Book 4 Ch 01 p24","steps":[{"prompt":"Find the heat output per hour: steam flow x (steam enthalpy - feed water enthalpy).","answer":"8000 kg/h x (665 - 85) kcal/kg = 4,640,000 kcal/h","explain":"Heat output is the useful energy added to the feed water to make steam. Feed water enthalpy is taken as 85 kcal/kg, equal to its temperature in kcal/kg."},{"prompt":"Find the heat input per hour: fuel flow x GCV.","answer":"1600 kg/h x 4000 kcal/kg = 6,400,000 kcal/h","explain":"Heat input is the total chemical energy of the fuel burnt, using the gross calorific value as the book requires."},{"prompt":"Compute the boiler efficiency.","answer":"4,640,000 / 6,400,000 x 100 = 72.5%","explain":"Efficiency is the ratio of heat output to heat input, expressed as a percentage."},{"prompt":"Compute the evaporation ratio.","answer":"8 TPH / 1.6 TPH = 5.0 kg steam per kg coal","explain":"Evaporation ratio is a quick indicator, but it does not show losses, so it must be read together with efficiency."}],"order":4108},
{"id":"p4-b01-030","paper":4,"topic":"Boiler Performance","kind":"problem","front":"In a 90% efficient boiler, a 1% error in the direct method changes efficiency by how much? In the indirect method, a 1% error in measured losses totalling 10% changes efficiency by how much?","back":"Direct: 90 +/- 0.9, i.e. 89.1 to 90.9%. Indirect: 100 - (10 +/- 0.1) = 90 +/- 0.1, i.e. 89.9 to 90.1%.","explain":"The same 1% measurement error has about nine times the effect on the direct result, because it applies to the whole input and output rather than a small loss. This is why the indirect method is preferred for accuracy.","flash":false,"source":"BEE Book 4 Ch 01 p25","steps":[{"prompt":"Find the direct-method error band for 90% efficiency with a 1% error.","answer":"90 x 1% = 0.9, so 90 +/- 0.9 = 89.1 to 90.9%","explain":"The error is applied to the efficiency itself, so it is a full 0.9 percentage points either way."},{"prompt":"Find the indirect-method error band with losses totalling 10%.","answer":"Losses 10 +/- 0.1, so efficiency = 100 - (10 +/- 0.1) = 90 +/- 0.1, i.e. 89.9 to 90.1%","explain":"A 1% error applied to the 10% losses is only 0.1 percentage points, so the result is much tighter."},{"prompt":"Compare the two error bands.","answer":"Direct band is 1.8 points wide; indirect band is 0.2 points wide","explain":"The indirect method stays accurate because measurement errors are on the small losses, not the large heat input."}],"order":4109},
{"id":"p4-b01-031","paper":4,"topic":"Boiler Performance","kind":"problem","front":"A coal-fired boiler (ultimate analysis: C 36%, H2 2.6%, O2 7.3%, S 0.6%, N2 1.1%, moisture 4.4%, ash 48%; GCV 3501 kcal/kg) is tested by the indirect method. Find the theoretical air required for complete combustion.","back":"4.79 kg of air per kg of coal.","explain":"Theoretical (stoichiometric) air is found from the ultimate analysis. Oxygen already in the fuel reduces the hydrogen that needs air, so it is subtracted.","flash":false,"source":"BEE Book 4 Ch 01 p34","steps":[{"prompt":"Write the theoretical air formula.","answer":"Theoretical air = [(11.6 x C) + (34.8 x (H2 - O2/8)) + (4.35 x S)] / 100 kg/kg of fuel","explain":"Each term is the air needed to burn carbon, hydrogen (net of fuel oxygen) and sulphur. The /100 converts percentages to kg per kg of fuel."},{"prompt":"Substitute the values.","answer":"[(11.6 x 36) + (34.8 x (2.6 - 7.3/8)) + (4.35 x 0.6)] / 100","explain":"Carbon 36%, hydrogen 2.6%, oxygen 7.3%, sulphur 0.6% from the fuel analysis."},{"prompt":"Evaluate.","answer":"= 4.79 kg of air per kg of coal","explain":"This value is needed for both the excess air and the actual air supplied calculations."}],"order":4110},
{"id":"p4-b01-032","paper":4,"topic":"Boiler Performance","kind":"problem","front":"Using the coal-fired boiler test (flue gas CO2 14%, average flue gas temperature 190 °C, ambient 31 °C, GCV 3501 kcal/kg), find the boiler efficiency by the indirect method.","back":"Efficiency = 74.41%. Total losses = 25.59%.","explain":"Each loss is calculated from the fuel analysis and flue gas data. Dry flue gas (7.1%) and unburnt carbon in bottom ash (9.87%) are the two largest losses.","flash":false,"source":"BEE Book 4 Ch 01 p35","steps":[{"prompt":"Find the theoretical CO2 in flue gas from fuel analysis.","answer":"Moles of C = 0.36/12 = 0.03; moles of N2 = (4.79 x 77/100 + 0.011)/28 = 0.1321; moles of S = 0.006/32 = 0.0001875. Theoretical CO2 = 0.03 / (0.03 + 0.1321 + 0.0001875) = 18.48%","explain":"Theoretical CO2 is the maximum CO2 you would see if fuel burnt with no excess air."},{"prompt":"Find the % excess air from measured CO2.","answer":"EA = 7900 x (18.48 - 14) / [14 x (100 - 18.48)] = 31%","explain":"The measured CO2 (14%) is lower than the theoretical value, which means extra air is present."},{"prompt":"Find the actual mass of air supplied and the dry flue gas mass.","answer":"AAS = (1 + 0.31) x 4.79 = 6.27 kg/kg coal. Dry flue gas = 6.51 kg/kg coal","explain":"Dry flue gas mass is the sum of CO2, N2 in fuel, N2 in air, excess O2 and SO2 mass, with H2O excluded."},{"prompt":"Calculate the first losses: L1 dry flue gas, L2 hydrogen, L3 fuel moisture, L4 air moisture, L5 CO.","answer":"L1 = 6.51 x 0.24 x (190 - 31) / 3501 x 100 = 7.1%; L2 = 4.36%; L3 = 0.82%; L4 = 0.25%; L5 = 2.2%","explain":"L5 uses the CO and CO2 readings and the carbon content of the coal: 0.55 x 0.36 x 5654 / (0.55 + 14) / 3501 x 100 = 2.2%."},{"prompt":"Calculate the radiation loss and the ash losses.","answer":"L6 = 0.37%; L7 fly ash = 0.62%; L8 bottom ash = 9.87%","explain":"Bottom ash is 90% of total ash and has GCV 800 kcal/kg, so its loss is large. Fly ash is only 10% of ash."},{"prompt":"Add all eight losses and subtract from 100.","answer":"Total losses = 7.1 + 4.36 + 0.82 + 0.25 + 2.2 + 0.37 + 0.62 + 9.87 = 25.59%. Efficiency = 100 - 25.59 = 74.41%","explain":"The answer shows that the largest recoverable losses in this example are the bottom ash and the dry flue gas."}],"order":4111},
{"id":"p4-b01-033","paper":4,"topic":"Boiler Performance","kind":"problem","front":"An oil-fired boiler has ultimate analysis C 84%, H2 12%, N2 0.5%, O2 1.5%, S 1.5%, moisture 0.5%; GCV 10,000 kcal/kg. Flue gas CO2 10.8%, O2 7.4%, flue gas temperature 190 °C, ambient 30 °C, humidity 0.025 kg/kg dry air. Find the boiler efficiency by the indirect method, ignoring radiation.","back":"Efficiency = 83.95% (radiation and convection assumed 0.38% in the book).","explain":"Oil-fired boilers have no ash losses, so only L1 to L5 apply. The dry flue gas loss (8.22%) and hydrogen loss (7.05%) make up most of the total.","flash":false,"source":"BEE Book 4 Ch 01 p38","steps":[{"prompt":"Find the theoretical air.","answer":"[(11.6 x 84) + (34.8 x (12 - 1.5/8)) + (4.35 x 1.5)] / 100 = 13.92 kg air/kg oil","explain":"Oil is entered as ultimate analysis, with no ash or moisture term needed in this formula."},{"prompt":"Find the excess air from measured O2.","answer":"EA = 7.4 / (21 - 7.4) x 100 = 54.4%","explain":"Using O2 is the recommended method; the 21 represents O2 in dry air."},{"prompt":"Find the actual air supplied and dry flue gas mass.","answer":"AAS = (1 + 0.544) x 13.92 = 21.49 kg/kg oil; dry flue gas = 21.4 kg/kg oil","explain":"Dry flue gas = AAS + fuel - (moisture + 9 x H2), which is 21.49 + 1 - (0.005 + 9 x 0.12) = 21.4."},{"prompt":"Calculate the losses.","answer":"L1 dry flue gas = 21.4 x 0.24 x (190 - 30) / 10000 x 100 = 8.22%; L2 hydrogen = 7.05%; L3 moisture in fuel = 0.033%; L4 moisture in air = 0.37%; L5 radiation = 0.38%","explain":"L5 is the radiation and convection loss, which the book calculates from surface temperature and wind speed."},{"prompt":"Compute the efficiency.","answer":"Total losses = 16.05%; efficiency = 100 - 16.05 = 83.95%","explain":"A simple dry flue gas check is shown by the book: a quick method gives the same 8.22% result."}],"order":4112},
{"id":"p4-b01-034","paper":4,"topic":"Boiler Performance","kind":"problem","front":"A 6 TPH oil-fired package boiler (carbon 86%, hydrogen 12%, oxygen 0.5%, sulphur 1.5%; GCV 10,000 kcal/kg; flue gas 240 °C; ambient 30 °C; O2 6%; feed water 85 °C; steam 10 kg/cm² at 665 kcal/kg; radiation and other losses 2.45%) has what boiler efficiency?","back":"Efficiency = 79% (calculated 78.99%).","explain":"Dry flue gas and hydrogen losses are the two large items. Adding the 2.45% radiation loss gives total losses near 21%. The book's sum shows 21.05% from rounding, but its own components add to 21.01%.","flash":false,"source":"BEE Book 4 Ch 01 p43","steps":[{"prompt":"Find the theoretical air and excess air.","answer":"Theoretical air = 14.2 kg/kg oil; EA = 6 / (21 - 6) x 100 = 40%","explain":"Theoretical air uses the carbon, hydrogen and sulphur percentages from the oil analysis."},{"prompt":"Find the actual air supplied and dry flue gas.","answer":"AAS = 14.2 x 1.4 = 19.88 kg/kg oil; dry flue gas = (19.88 + 1) - 9 x 0.12 = 19.8 kg/kg oil","explain":"Dry flue gas mass is the same whether computed by the detailed sum or the simple method."},{"prompt":"Calculate L1 dry flue gas loss.","answer":"19.8 x 0.27 x (240 - 30) / 10000 x 100 = 11.23%","explain":"Specific heat 0.27 kcal/kg C is for the flue gas. The temperature difference is 210 C."},{"prompt":"Calculate L2 hydrogen loss.","answer":"9 x 0.12 x [584 + 0.45 x (240 - 30)] / 10000 x 100 = 7.33%","explain":"The 584 kcal/kg is the latent heat of the water vapour formed from hydrogen."},{"prompt":"Add the losses and find efficiency.","answer":"Total = 11.23 + 7.33 + 2.45 = 21.01%; efficiency = 100 - 21.01 = 78.99%, say 79%","explain":"The book prints 21.05% for the total, a small arithmetic slip; the efficiency 78.99% matches the correct sum."}],"order":4113}
]$cards$::jsonb);
